<script>
(()=>{const form=document.getElementById('due-collection-form');if(!form)return;const amount=document.getElementById('collection-amount'),method=document.getElementById('collection-method'),reference=document.getElementById('collection-reference'),preview=document.getElementById('collection-balance-preview');const due={{ (float)$order->due_amount }};function update(){reference.required=method.value!=='Cash';const value=Number(amount.value);preview.textContent=Number.isFinite(value)&&value>0&&value<=due?'Remaining after collection: BDT '+(due-value).toFixed(2):'Enter an amount within the current outstanding balance.';}amount.addEventListener('input',update);method.addEventListener('change',update);form.addEventListener('submit',event=>{if(form.dataset.busy){event.preventDefault();return;}if(!confirm('Confirm that this payment has been received? A permanent receipt will be recorded.')){event.preventDefault();return;}form.dataset.busy='1';form.querySelector('button[type=submit]').disabled=true;});update();})();
</script>
